// Recursion template (fragment)
static Result solve(Input in) {
    if (isSmallEnough(in)) return directAnswer(in);      // base case
    Input[] parts = split(in);                           // strictly smaller inputs
    Result[] sub = new Result[parts.length];
    for (int i = 0; i < parts.length; i++) sub[i] = solve(parts[i]);   // trust the calls
    return combine(sub);                                 // build this answer
}

import java.util.*;

public class Main {
    static long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }

    static double myPow(double x, int n) {
        long e = n;                    // widen first: -Integer.MIN_VALUE overflows int
        if (e < 0) { x = 1 / x; e = -e; }
        double result = 1;
        while (e > 0) {
            if ((e & 1) == 1) result *= x;
            x *= x;
            e >>= 1;
        }
        return result;
    }

    static void mergeSort(int[] a, int lo, int hi, int[] tmp) {   // sorts a[lo, hi)
        if (hi - lo < 2) return;
        int mid = lo + (hi - lo) / 2;
        mergeSort(a, lo, mid, tmp);
        mergeSort(a, mid, hi, tmp);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi) tmp[k++] = a[j++];
        System.arraycopy(tmp, lo, a, lo, hi - lo);
    }

    static int moves = 0;
    static void hanoi(int n, char from, char to, char via, boolean print) {
        if (n == 0) return;
        hanoi(n - 1, from, via, to, print);       // park n-1 disks on the spare peg
        moves++;
        if (print) System.out.println("move disk " + n + " " + from + " -> " + to);
        hanoi(n - 1, via, to, from, print);       // bring them on top of disk n
    }

    static final Random RNG = new Random(7);
    static int quickSelect(int[] a, int k) {      // k-th smallest, 0-based
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int p = partition(a, lo, hi);
            if (p == k) return a[p];
            if (p < k) lo = p + 1; else hi = p - 1;
        }
        return a[lo];
    }
    static int partition(int[] a, int lo, int hi) {
        swap(a, lo + RNG.nextInt(hi - lo + 1), hi);   // random pivot goes to the end
        int pivot = a[hi], i = lo;
        for (int j = lo; j < hi; j++) if (a[j] < pivot) swap(a, i++, j);
        swap(a, i, hi);                           // pivot lands in its final position
        return i;
    }
    static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

    static int fibCalls = 0;
    static long fibSlow(int n) { fibCalls++; return n < 2 ? n : fibSlow(n - 1) + fibSlow(n - 2); }
    static long fibMemo(int n, long[] memo) {
        if (n < 2) return n;
        if (memo[n] != 0) return memo[n];
        return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
    }
    static int deep(int n) { return deep(n + 1) + 1; }

    public static void main(String[] args) {
        System.out.println("fact(5) = " + fact(5));
        System.out.println("myPow(2, 10) = " + myPow(2, 10));
        System.out.println("myPow(2, -2) = " + myPow(2, -2));
        System.out.println("myPow(2, MIN) = " + myPow(2, Integer.MIN_VALUE));
        int[] arr = {38, 27, 43, 3, 9, 82, 10};
        mergeSort(arr, 0, arr.length, new int[arr.length]);
        System.out.println("sorted = " + Arrays.toString(arr));
        hanoi(3, 'A', 'C', 'B', true);
        moves = 0; hanoi(20, 'A', 'C', 'B', false);
        System.out.println("hanoi(20) moves = " + moves);
        int[] b = {7, 10, 4, 3, 20, 15};
        System.out.println("3rd smallest = " + quickSelect(b.clone(), 2));
        System.out.println("2nd largest = " + quickSelect(b.clone(), b.length - 2));
        System.out.println("fibSlow(30) = " + fibSlow(30) + " calls=" + fibCalls);
        System.out.println("fibMemo(30) = " + fibMemo(30, new long[31]));
        try { deep(1); }
        catch (StackOverflowError e) { System.out.println("StackOverflowError caught"); }
    }
}

// Backtracking template (fragment)
static void backtrack(State s, List<Integer> path, List<List<Integer>> out) {
    if (isGoal(s)) {                          // 1. record an answer (copy the path!)
        out.add(new ArrayList<>(path));
        return;                               //    or keep going, e.g. subsets record at every node
    }
    for (int choice : candidates(s)) {        // 2. loop over the options at this step
        if (!isValid(s, choice)) continue;    //    prune early
        path.add(choice);                     // 3. choose
        backtrack(next(s, choice), path, out);    // 4. explore
        path.remove(path.size() - 1);         // 5. unchoose
    }
}

import java.util.*;

public class Main {
    // 1. Subsets (distinct values)
    static List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> out = new ArrayList<>();
        subsetsRec(nums, 0, new ArrayList<>(), out);
        return out;
    }
    static void subsetsRec(int[] nums, int start, List<Integer> path, List<List<Integer>> out) {
        out.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            subsetsRec(nums, i + 1, path, out);
            path.remove(path.size() - 1);
        }
    }

    // 2. Subsets II (duplicates in input)
    static List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> out = new ArrayList<>();
        dupRec(nums, 0, new ArrayList<>(), out);
        return out;
    }
    static void dupRec(int[] nums, int start, List<Integer> path, List<List<Integer>> out) {
        out.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            if (i > start && nums[i] == nums[i - 1]) continue;   // skip same value at this level
            path.add(nums[i]);
            dupRec(nums, i + 1, path, out);
            path.remove(path.size() - 1);
        }
    }

    // 3. Permutations (distinct values) with a used[] array
    static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> out = new ArrayList<>();
    permRec(nums, new boolean[nums.length], new ArrayList<>(), out);
    return out;
}
static void permRec(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> out) {
    if (path.size() == nums.length) { out.add(new ArrayList<>(path)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        permRec(nums, used, path, out);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}

// 4. Permutations II (duplicates)
static List<List<Integer>> permuteUnique(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> out = new ArrayList<>();
    uniqRec(nums, new boolean[nums.length], new ArrayList<>(), out);
    return out;
}
static void uniqRec(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> out) {
    if (path.size() == nums.length) { out.add(new ArrayList<>(path)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
        used[i] = true;
        path.add(nums[i]);
        uniqRec(nums, used, path, out);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}

// 5. Combinations C(n, k)
static List<List<Integer>> combine(int n, int k) {
    List<List<Integer>> out = new ArrayList<>();
    combRec(n, k, 1, new ArrayList<>(), out);
    return out;
}
static void combRec(int n, int k, int start, List<Integer> path, List<List<Integer>> out) {
    if (path.size() == k) { out.add(new ArrayList<>(path)); return; }
    // prune: need (k - path.size()) more numbers, so i can be at most n - need + 1
    for (int i = start; i <= n - (k - path.size()) + 1; i++) {
        path.add(i);
        combRec(n, k, i + 1, path, out);
        path.remove(path.size() - 1);
    }
}

// 6. Combination Sum (reuse allowed)
static List<List<Integer>> combinationSum(int[] cand, int target) {
    Arrays.sort(cand);
    List<List<Integer>> out = new ArrayList<>();
    csRec(cand, target, 0, new ArrayList<>(), out);
    return out;
}
static void csRec(int[] c, int remain, int start, List<Integer> path, List<List<Integer>> out) {
    if (remain == 0) { out.add(new ArrayList<>(path)); return; }
    for (int i = start; i < c.length; i++) {
        if (c[i] > remain) break;               // sorted, so everything after is too big
        path.add(c[i]);
        csRec(c, remain - c[i], i, path, out);  // i, not i + 1: same number may be reused
        path.remove(path.size() - 1);
    }
}

// 7. Letter combinations
static final String[] KEYS = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
static List<String> letterCombinations(String digits) {
    List<String> out = new ArrayList<>();
    if (digits.isEmpty()) return out;
    lcRec(digits, 0, new StringBuilder(), out);
    return out;
    }
    static void lcRec(String d, int idx, StringBuilder sb, List<String> out) {
        if (idx == d.length()) { out.add(sb.toString()); return; }
        for (char ch : KEYS[d.charAt(idx) - '0'].toCharArray()) {
            sb.append(ch);
            lcRec(d, idx + 1, sb, out);
            sb.setLength(sb.length() - 1);
        }
    }

    // 8. Generate parentheses
    static List<String> generateParenthesis(int n) {
        List<String> out = new ArrayList<>();
        gpRec(n, 0, 0, new StringBuilder(), out);
        return out;
    }
    static void gpRec(int n, int open, int close, StringBuilder sb, List<String> out) {
        if (sb.length() == 2 * n) { out.add(sb.toString()); return; }
        if (open < n) {
            sb.append('(');
            gpRec(n, open + 1, close, sb, out);
            sb.setLength(sb.length() - 1);
        }
        if (close < open) {
            sb.append(')');
            gpRec(n, open, close + 1, sb, out);
            sb.setLength(sb.length() - 1);
        }
    }

    public static void main(String[] args) {
        System.out.println("subsets [1,2,3]        = " + subsets(new int[]{1, 2, 3}));
        System.out.println("subsets II [1,2,2]     = " + subsetsWithDup(new int[]{2, 1, 2}));
        System.out.println("permute [1,2,3]        = " + permute(new int[]{1, 2, 3}));
        System.out.println("permuteUnique [1,1,2]  = " + permuteUnique(new int[]{1, 1, 2}));
        System.out.println("combine(4, 2)          = " + combine(4, 2));
        System.out.println("combinationSum [2,3,5] = " + combinationSum(new int[]{5, 3, 2}, 8));
        System.out.println("letters \"23\"           = " + letterCombinations("23"));
        System.out.println("parens(3)              = " + generateParenthesis(3));
        System.out.println("count parens(8)        = " + generateParenthesis(8).size());
        int[] eight = {1, 2, 3, 4, 5, 6, 7, 8};
        System.out.println("count permute(8)       = " + permute(eight).size());
    }
}

// Constraint search (fragment): returns true as soon as one complete solution exists
static boolean solve(State s) {
    if (complete(s)) return true;
    for (Move m : movesFrom(s)) {
        if (!legal(s, m)) continue;       // prune: never enter an illegal state
        apply(s, m);                      // choose, mutating shared state
        if (solve(s)) return true;        // explore (stop at the first success)
        undo(s, m);                       // unchoose
    }
    return false;                         // every move failed: tell the caller to backtrack
}

import java.util.*;

public class Main {
    // ---------- Word Search ----------
    static boolean exist(char[][] board, String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(board, word, 0, r, c)) return true;
        return false;
    }
    static boolean dfs(char[][] b, String w, int k, int r, int c) {
        if (k == w.length()) return true;
        if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return false;
        if (b[r][c] != w.charAt(k)) return false;
        char saved = b[r][c];
        b[r][c] = '#';                                   // choose: mark visited
        boolean found = dfs(b, w, k + 1, r + 1, c) || dfs(b, w, k + 1, r - 1, c)
                     || dfs(b, w, k + 1, r, c + 1) || dfs(b, w, k + 1, r, c - 1);
        b[r][c] = saved;                                 // unchoose
        return found;
    }

    // ---------- N-Queens ----------
    static List<List<String>> solveNQueens(int n) {
        List<List<String>> out = new ArrayList<>();
        place(n, 0, new int[n], new boolean[n], new boolean[2 * n], new boolean[2 * n], out);
        return out;
    }
    static void place(int n, int r, int[] q, boolean[] col, boolean[] d1, boolean[] d2,
                      List<List<String>> out) {
        if (r == n) {
            List<String> board = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                char[] row = new char[n];
                Arrays.fill(row, '.');
                row[q[i]] = 'Q';
                board.add(new String(row));
            }
            out.add(board);
            return;
        }
        for (int c = 0; c < n; c++) {
            int a = r + c, b = r - c + n;
            if (col[c] || d1[a] || d2[b]) continue;
            col[c] = d1[a] = d2[b] = true;
            q[r] = c;
            place(n, r + 1, q, col, d1, d2, out);
            col[c] = d1[a] = d2[b] = false;
        }
    }

    // ---------- Palindrome Partitioning ----------
    static List<List<String>> partition(String s) {
        List<List<String>> out = new ArrayList<>();
        part(s, 0, new ArrayList<>(), out);
        return out;
    }
    static void part(String s, int start, List<String> path, List<List<String>> out) {
        if (start == s.length()) { out.add(new ArrayList<>(path)); return; }
        for (int end = start + 1; end <= s.length(); end++) {
            if (!isPal(s, start, end - 1)) continue;     // prune: only palindromic pieces
            path.add(s.substring(start, end));
            part(s, end, path, out);
            path.remove(path.size() - 1);
        }
    }
    static boolean isPal(String s, int i, int j) {
        while (i < j) if (s.charAt(i++) != s.charAt(j--)) return false;
        return true;
    }

    // ---------- Sudoku ----------
    static int nodes = 0;
    static boolean solveSudoku(char[][] g) {
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++) {
                if (g[r][c] != '.') continue;
                for (char d = '1'; d <= '9'; d++) {
                    if (!ok(g, r, c, d)) continue;
                    g[r][c] = d; nodes++;
                    if (solveSudoku(g)) return true;
                    g[r][c] = '.';
                }
                return false;                            // no digit fits this cell: dead end
            }
        return true;                                     // no empty cell left
    }
    static boolean ok(char[][] g, int r, int c, char d) {
        for (int i = 0; i < 9; i++) {
            if (g[r][i] == d || g[i][c] == d) return false;
            if (g[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == d) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        char[][] board = {
            {'A', 'B', 'C', 'E'},
            {'S', 'F', 'C', 'S'},
            {'A', 'D', 'E', 'E'}};
        System.out.println("ABCCED: " + exist(board, "ABCCED"));
        System.out.println("SEE:    " + exist(board, "SEE"));
        System.out.println("ABCB:   " + exist(board, "ABCB"));

        for (List<String> sol : solveNQueens(4)) {
            System.out.println(String.join("\n", sol));
            System.out.println();
        }
        for (int n = 1; n <= 9; n++) System.out.print(solveNQueens(n).size() + " ");
        System.out.println("<- solutions for n = 1..9");

        System.out.println(partition("aab"));

        String[] puzzle = {
            "53..7....", "6..195...", ".98....6.", "8...6...3", "4..8.3..1",
            "7...2...6", ".6....28.", "...419..5", "....8..79"};
        char[][] g = new char[9][];
        for (int i = 0; i < 9; i++) g[i] = puzzle[i].toCharArray();
        boolean solved = solveSudoku(g);
        System.out.println("solved=" + solved + " placements=" + nodes);
        for (char[] row : g) System.out.println(new String(row));
    }
}

// Bottom-up: answer for a subtree is built from the answers of its children (fragment)
static int solve(TreeNode n) {
    if (n == null) return BASE;                 // empty tree: 0 for height, true for balanced
    int l = solve(n.left);
    int r = solve(n.right);
    best = Math.max(best, combineForAnswer(n, l, r));   // optional global answer
    return combineForParent(n, l, r);                    // what the parent needs
}

// Top-down: information flows in through parameters (fragment)
static boolean solve(TreeNode n, int carried) {
    if (n == null) return BASE;
    int next = update(carried, n);
    return solve(n.left, next) && solve(n.right, next);
}

import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    // Build from a level-order array where null means "no node" (LeetCode style).
    static TreeNode build(Integer... vals) {
        if (vals.length == 0 || vals[0] == null) return null;
        TreeNode root = new TreeNode(vals[0]);
        Deque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < vals.length) {
            TreeNode cur = q.poll();
            if (vals[i] != null) { cur.left = new TreeNode(vals[i]); q.add(cur.left); }
            i++;
            if (i < vals.length && vals[i] != null) {
                cur.right = new TreeNode(vals[i]);
                q.add(cur.right);
            }
            i++;
        }
        return root;
    }

    // ---- recursive traversals ----
static void pre(TreeNode n, List<Integer> out) {
    if (n == null) return;
    out.add(n.val);                 // node first
    pre(n.left, out);
    pre(n.right, out);
}
static void in(TreeNode n, List<Integer> out) {
    if (n == null) return;
    in(n.left, out);
    out.add(n.val);                 // node in the middle
    in(n.right, out);
}
static void post(TreeNode n, List<Integer> out) {
    if (n == null) return;
    post(n.left, out);
    post(n.right, out);
    out.add(n.val);                 // node last
}

// ---- iterative traversals ----
static List<Integer> inorderIter(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> stack = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !stack.isEmpty()) {
        while (cur != null) { stack.push(cur); cur = cur.left; }   // go as far left as possible
        cur = stack.pop();
        out.add(cur.val);                                          // visit
        cur = cur.right;                                           // then the right subtree
    }
    return out;
}
static List<Integer> preorderIter(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    if (root == null) return out;
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        TreeNode n = stack.pop();
        out.add(n.val);
        if (n.right != null) stack.push(n.right);   // right first so left is popped first
        if (n.left != null) stack.push(n.left);
    }
    return out;
}
static List<Integer> postorderIter(TreeNode root) {
    LinkedList<Integer> out = new LinkedList<>();
    if (root == null) return out;
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {                       // reversed "root, right, left"
        TreeNode n = stack.pop();
        out.addFirst(n.val);
        if (n.left != null) stack.push(n.left);
        if (n.right != null) stack.push(n.right);
    }
    return out;
}

// ---- classic DFS problems ----
static int height(TreeNode n) {
    return n == null ? 0 : 1 + Math.max(height(n.left), height(n.right));
}

static int diameter;                      // longest path measured in edges
static int diameterOf(TreeNode root) { diameter = 0; depth(root); return diameter; }
static int depth(TreeNode n) {
    if (n == null) return 0;
    int l = depth(n.left), r = depth(n.right);
    diameter = Math.max(diameter, l + r);  // path that bends at this node
    return 1 + Math.max(l, r);             // path that continues up to the parent
}

static boolean sameTree(TreeNode a, TreeNode b) {
    if (a == null || b == null) return a == b;
        return a.val == b.val && sameTree(a.left, b.left) && sameTree(a.right, b.right);
    }

    static boolean hasPathSum(TreeNode n, int target) {
        if (n == null) return false;
        if (n.left == null && n.right == null) return n.val == target;   // must end at a leaf
        return hasPathSum(n.left, target - n.val) || hasPathSum(n.right, target - n.val);
    }

    static int bestPath;                      // max path sum (values may be negative)
    static int maxPathSum(TreeNode root) {
        bestPath = Integer.MIN_VALUE;
        gain(root);
        return bestPath;
    }
    static int gain(TreeNode n) {
        if (n == null) return 0;
        int l = Math.max(0, gain(n.left));     // ignore a negative branch
        int r = Math.max(0, gain(n.right));
        bestPath = Math.max(bestPath, n.val + l + r);   // bend here
        return n.val + Math.max(l, r);                  // extend upward
    }

    static TreeNode invert(TreeNode n) {
        if (n == null) return null;
        TreeNode t = n.left; n.left = invert(n.right); n.right = invert(t);
        return n;
    }

    // Balanced: returns height, or -1 if unbalanced anywhere (one pass, O(n))
    static boolean isBalanced(TreeNode root) { return check(root) != -1; }
    static int check(TreeNode n) {
        if (n == null) return 0;
        int l = check(n.left); if (l == -1) return -1;
        int r = check(n.right); if (r == -1) return -1;
        if (Math.abs(l - r) > 1) return -1;
        return 1 + Math.max(l, r);
    }

    public static void main(String[] args) {
        TreeNode t = build(1, 2, 3, 4, 5, null, 6);
        List<Integer> a = new ArrayList<>(), b = new ArrayList<>(), c = new ArrayList<>();
        pre(t, a); in(t, b); post(t, c);
        System.out.println("preorder  " + a + " iter " + preorderIter(t));
        System.out.println("inorder   " + b + " iter " + inorderIter(t));
        System.out.println("postorder " + c + " iter " + postorderIter(t));
        System.out.println("height = " + height(t));
        System.out.println("diameter = " + diameterOf(build(1, 2, 3, 4, 5)));
        System.out.println("same tree = " + sameTree(build(1, 2, 3), build(1, 2, 3))
                + ", " + sameTree(build(1, 2), build(1, null, 2)));
