static List<List<Integer>> zigzag(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Deque<TreeNode> q = new ArrayDeque<>();
    q.offer(root);
    boolean leftToRight = true;
    while (!q.isEmpty()) {
        int size = q.size();
        LinkedList<Integer> level = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            TreeNode n = q.poll();
            if (leftToRight) level.addLast(n.val); else level.addFirst(n.val);
            if (n.left != null) q.offer(n.left);
            if (n.right != null) q.offer(n.right);
        }
        res.add(level);
        leftToRight = !leftToRight;
    }
    return res;
}

static List<Integer> rightSideView(TreeNode root) {
    List<Integer> view = new ArrayList<>();
    if (root == null) return view;
    Deque<TreeNode> q = new ArrayDeque<>();
    q.offer(root);
    while (!q.isEmpty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            TreeNode n = q.poll();
            if (i == size - 1) view.add(n.val);       // last node of the level
            if (n.left != null) q.offer(n.left);
            if (n.right != null) q.offer(n.right);
        }
    }
    return view;
}

static int minDepth(TreeNode root) {
    if (root == null) return 0;
    Deque<TreeNode> q = new ArrayDeque<>();
    q.offer(root);
    int depth = 1;
    while (!q.isEmpty()) {
        for (int i = q.size(); i > 0; i--) {
            TreeNode n = q.poll();
            if (n.left == null && n.right == null) return depth;   // first leaf = shallowest
            if (n.left != null) q.offer(n.left);
            if (n.right != null) q.offer(n.right);
        }
        depth++;
    }
    return depth;
}

// Connect next pointers on ANY binary tree, O(1) extra space (uses the next links themselves)
static void connect(TreeNode root) {
    TreeNode levelStart = root;
    while (levelStart != null) {
        TreeNode dummy = new TreeNode(0), tail = dummy;
        for (TreeNode n = levelStart; n != null; n = n.next) {
            if (n.left != null)  { tail.next = n.left;  tail = tail.next; }
            if (n.right != null) { tail.next = n.right; tail = tail.next; }
        }
        levelStart = dummy.next;           // the first node of the next level
    }
}
    // Serialize / deserialize with BFS and "null" markers (LinkedList allows null elements)
    static String serialize(TreeNode root) {
        List<String> out = new ArrayList<>();
