    // ---- validate BST: every node must lie inside the open interval (lo, hi) ----
    static boolean isValidBST(TreeNode n, long lo, long hi) {
        if (n == null) return true;
        if (n.val <= lo || n.val >= hi) return false;
        return isValidBST(n.left, lo, n.val) && isValidBST(n.right, n.val, hi);
    }

    // ---- kth smallest: stop the iterative inorder after k pops ----
    static int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) { stack.push(cur); cur = cur.left; }
            cur = stack.pop();
            if (--k == 0) return cur.val;
            cur = cur.right;
        }
        throw new IllegalArgumentException("k out of range");
    }

    // ---- LCA in a BST: walk down using the ordering ----
    static TreeNode lcaBST(TreeNode root, int p, int q) {
        TreeNode cur = root;
        while (cur != null) {
            if (p < cur.val && q < cur.val) cur = cur.left;
            else if (p > cur.val && q > cur.val) cur = cur.right;
            else return cur;                       // paths diverge here (or one equals cur)
        }
        return null;
    }

    // ---- LCA in a general binary tree ----
    static TreeNode lca(TreeNode n, TreeNode p, TreeNode q) {
    if (n == null || n == p || n == q) return n;
    TreeNode l = lca(n.left, p, q), r = lca(n.right, p, q);
    return (l != null && r != null) ? n : (l != null ? l : r);
}
static TreeNode find(TreeNode n, int v) {
    if (n == null || n.val == v) return n;
    TreeNode l = find(n.left, v);
    return l != null ? l : find(n.right, v);
}

// ---- build from preorder + inorder ----
static int pre;                                       // next index in preorder
static Map<Integer, Integer> pos;                     // value -> index in inorder
static TreeNode buildTree(int[] preorder, int[] inorder, boolean trace) {
    pos = new HashMap<>();
    for (int i = 0; i < inorder.length; i++) pos.put(inorder[i], i);
    pre = 0;
    return construct(preorder, 0, inorder.length - 1, trace);
}
static TreeNode construct(int[] preorder, int lo, int hi, boolean trace) {
    if (lo > hi) return null;
    int rootVal = preorder[pre++];
    int mid = pos.get(rootVal);
    if (trace) System.out.println("root=" + rootVal + " | inorder range [" + lo + ", " + hi
            + "] | split at " + mid + " | left size " + (mid - lo)
            + ", right size " + (hi - mid));
    TreeNode node = new TreeNode(rootVal);
    node.left = construct(preorder, lo, mid - 1, trace);     // left BEFORE right
    node.right = construct(preorder, mid + 1, hi, trace);
    return node;
}

// ---- BST iterator (amortised O(1) next, O(h) memory) ----
static class BSTIterator {
    private final Deque<TreeNode> stack = new ArrayDeque<>();
    BSTIterator(TreeNode root) { pushLeft(root); }
    private void pushLeft(TreeNode n) { for (; n != null; n = n.left) stack.push(n); }
    boolean hasNext() { return !stack.isEmpty(); }
    int next() {
        TreeNode n = stack.pop();
        pushLeft(n.right);
        return n.val;
    }
}

// ---- sorted array -> height-balanced BST ----
static TreeNode sortedArrayToBST(int[] a, int lo, int hi) {
    if (lo > hi) return null;
    int mid = lo + (hi - lo) / 2;
    TreeNode n = new TreeNode(a[mid]);
    n.left = sortedArrayToBST(a, lo, mid - 1);
    n.right = sortedArrayToBST(a, mid + 1, hi);
    return n;
}

// ---- BST search / insert / delete ----
static TreeNode insert(TreeNode n, int v) {
    if (n == null) return new TreeNode(v);
    if (v < n.val) n.left = insert(n.left, v); else n.right = insert(n.right, v);
    return n;
}
static TreeNode delete(TreeNode n, int key) {
    if (n == null) return null;
    if (key < n.val) n.left = delete(n.left, key);
    else if (key > n.val) n.right = delete(n.right, key);
    else {
        if (n.left == null) return n.right;          // zero or one child: splice out
        if (n.right == null) return n.left;
        TreeNode succ = n.right;                     // two children: smallest of right subtree
        while (succ.left != null) succ = succ.left;
        n.val = succ.val;
        n.right = delete(n.right, succ.val);
    }
    return n;
}
    static List<Integer> preorder(TreeNode n) {
