import java.util.*;

public class Main {
    static class Trie {
        private static class Node {
            Node[] next = new Node[26];
            boolean end;                       // a word finishes at this node
            int pass;                          // how many words pass through (for counts)
        }
        private final Node root = new Node();
        int nodes = 1;

        void insert(String word, boolean trace) {
            Node cur = root;
            for (char ch : word.toCharArray()) {
                int i = ch - 'a';
                boolean created = cur.next[i] == null;
                if (created) { cur.next[i] = new Node(); nodes++; }
                cur = cur.next[i];
                cur.pass++;
                if (trace) System.out.println("insert " + word + " | char " + ch + " | "
                        + (created ? "create node" : "reuse node") + " | pass=" + cur.pass);
            }
            cur.end = true;
        }
        void insert(String word) { insert(word, false); }

        private Node walk(String s) {          // follow s from the root, or null if it breaks
            Node cur = root;
            for (char ch : s.toCharArray()) {
                cur = cur.next[ch - 'a'];
                if (cur == null) return null;
            }
            return cur;
        }
        boolean search(String w)     { Node n = walk(w); return n != null && n.end; }
        boolean startsWith(String p) { return walk(p) != null; }
        int countPrefix(String p)    { Node n = walk(p); return n == null ? 0 : n.pass; }

        // autocomplete: up to k words with the prefix, in alphabetical order
        List<String> suggest(String prefix, int k) {
            List<String> out = new ArrayList<>();
            Node n = walk(prefix);
            if (n != null) collect(n, new StringBuilder(prefix), out, k);
            return out;
        }
        private void collect(Node n, StringBuilder sb, List<String> out, int k) {
            if (out.size() == k) return;
            if (n.end) out.add(sb.toString());
        for (int i = 0; i < 26 && out.size() < k; i++) {
            if (n.next[i] == null) continue;
            sb.append((char) ('a' + i));
            collect(n.next[i], sb, out, k);
            sb.setLength(sb.length() - 1);
        }
    }

    // wildcard search: '.' matches any one letter
    boolean searchWild(String w) { return wild(root, w, 0); }
    private boolean wild(Node n, String w, int idx) {
        if (n == null) return false;
        if (idx == w.length()) return n.end;
        char ch = w.charAt(idx);
        if (ch != '.') return wild(n.next[ch - 'a'], w, idx + 1);
        for (Node child : n.next) if (child != null && wild(child, w, idx + 1)) return true;
        return false;
    }
}

