static List<String> findWords(char[][] board, String[] words) {
    TNode root = new TNode();
    for (String w : words) {
        TNode cur = root;
        for (char ch : w.toCharArray()) {
            if (cur.next[ch - 'a'] == null) cur.next[ch - 'a'] = new TNode();
            cur = cur.next[ch - 'a'];
        }
        cur.word = w;
    }
    List<String> found = new ArrayList<>();
    for (int r = 0; r < board.length; r++)
        for (int c = 0; c < board[0].length; c++) dfs(board, r, c, root, found);
    return found;
}
static void dfs(char[][] b, int r, int c, TNode parent, List<String> found) {
    if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return;
    char ch = b[r][c];
    if (ch == '#' || parent.next[ch - 'a'] == null) return;     // visited, or no word continues
    TNode node = parent.next[ch - 'a'];
    if (node.word != null) { found.add(node.word); node.word = null; }   // report once
    b[r][c] = '#';
    dfs(b, r + 1, c, node, found);
    dfs(b, r - 1, c, node, found);
    dfs(b, r, c + 1, node, found);
    dfs(b, r, c - 1, node, found);
    b[r][c] = ch;
}

// ---- XOR trie: maximum XOR of two numbers (bitwise trie of 31 bits) ----
static int maxXor(int[] nums) {
    int[][] child = new int[nums.length * 31 + 2][2];     // child[node][bit], 0 = none
    int size = 1;
    for (int x : nums) {
        int cur = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (child[cur][bit] == 0) child[cur][bit] = size++;
            cur = child[cur][bit];
        }
    }
    int best = 0;
    for (int x : nums) {
        int cur = 0, val = 0;
        for (int b = 30; b >= 0; b--) {
            int want = 1 - ((x >> b) & 1);                 // opposite bit makes the XOR bit 1
            if (child[cur][want] != 0) { val |= 1 << b; cur = child[cur][want]; }
            else cur = child[cur][1 - want];
        }
        best = Math.max(best, val);
        }
        return best;
    }

